// DINERO 30-oct-2026 18:00 · Mito: cambiarte de banco borra tu cuenta en negativo (método V2)
// Metáfora: el saldo rojo se vuelve una FICHA roja que viaja por un tubo hasta el archivo de la
// agencia y de ahí la consulta el siguiente banco.
// Sitios: A = la calle de los bancos (azul marino, luz arriba a la izquierda);
//         B = el archivo de la agencia por dentro (verde oscuro, cajones).
import React from 'react';
import {AbsoluteFill, Easing, interpolate, clamp, useS, en, golpe, sacudida, Etiqueta, Contador, Carita, Camara, Destello, Ondas, Estela, FONT} from './kit';

export const SUBS = {acento: '#FFC83D'};

const ORO = '#FFC83D';
const ROJO = '#FF4D4D';

const T_CAMBIA = en('Cambiarte');
const T_BORRA = en('borra');
const T_NEGATIVO = en('negativo');
const T_CUARENTA = en('cuarenta');
const T_SOBRE = en('sobregiro');
const T_CERRAR = en('cerrar');
const T_REPORTARLA = en('reportarla');
const T_REPORTE = en('reporte');
const T_AGENCIA = en('agencia');
const T_HISTORIAL = en('historial');
const T_SIGUIENTE = en('siguiente');
const T_CONSULTA = en('consulta');
const T_ABRIRTE = en('abrirte');
const T_SIETE = en('siete');
const T_QUINCENAS = en('quincenas');
const T_GRATIS = en('gratis');
const T_ERRORES = en('errores');
const T_NEGOCIA = en('negocia');
const T_ESCRITO = en('escrito');
const T_ENVIA = en('Envíaselo');
const T_ROJO2 = en('rojo', 2);

const FondoSitio: React.FC<{verde: boolean}> = ({verde}) => {
  const {s} = useS();
  const c = verde ? ['#2a5a48', '#11302a', '#040f0b'] : ['#26467f', '#10224d', '#040a1b'];
  return (
    <AbsoluteFill style={{background: `radial-gradient(ellipse at 26% 20%, ${c[0]} 0%, ${c[1]} 50%, ${c[2]} 100%)`}}>
      <div style={{position: 'absolute', left: -220, top: -240, width: 940, height: 940, borderRadius: 940, background: 'radial-gradient(circle, rgba(255,222,160,0.16), transparent 64%)'}} />
      {/* edificios lejanos desenfocados */}
      <svg width={1080} height={1920} style={{position: 'absolute', opacity: 0.22, filter: 'blur(3px)'}}>
        {Array.from({length: 9}).map((_, i) => <rect key={i} x={i * 125 - 20} y={760 - ((i * 97) % 260)} width={110} height={900} fill={verde ? '#0b2a20' : '#0a1838'} />)}
      </svg>
      {Array.from({length: 8}).map((_, i) => {
        const r = 90 + ((i * 53) % 120);
        return <div key={i} style={{position: 'absolute', left: ((i * 263) % 1160) - 60 + Math.sin(s * 0.32 + i) * 30, top: ((i * 409) % 1900) + Math.cos(s * 0.29 + i) * 40, width: r, height: r, borderRadius: r, background: i % 3 ? 'rgba(130,170,255,0.09)' : 'rgba(255,200,61,0.09)', filter: 'blur(24px)'}} />;
      })}
      <AbsoluteFill style={{background: 'radial-gradient(circle at 50% 50%, transparent 50%, rgba(0,0,0,0.66) 100%)'}} />
    </AbsoluteFill>
  );
};

const Defs: React.FC = () => (
  <defs>
    <linearGradient id="bancoG" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stopColor="#e8eef9" />
      <stop offset="60%" stopColor="#9fb0cf" />
      <stop offset="100%" stopColor="#5b6b8e" />
    </linearGradient>
    <linearGradient id="fichaG" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stopColor="#ff9a9a" />
      <stop offset="100%" stopColor="#b52a2a" />
    </linearGradient>
    <linearGradient id="cajonG" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stopColor="#7fa38f" />
      <stop offset="100%" stopColor="#2f5444" />
    </linearGradient>
  </defs>
);

// Edificio de banco con volumen
const Banco: React.FC<{x: number; y: number; k?: number; cerrado?: number; lupa?: number}> = ({x, y, k = 1, cerrado = 0, lupa = 0}) => {
  const {s} = useS();
  return (
    <g transform={`translate(${x} ${y}) scale(${k})`}>
      <ellipse cx={10} cy={20} rx={240} ry={26} fill="rgba(0,0,0,0.4)" />
      <polygon points="-230,-330 0,-450 230,-330" fill="url(#bancoG)" stroke="#3d4a68" strokeWidth={6} />
      <rect x={-210} y={-330} width={420} height={330} fill="url(#bancoG)" stroke="#3d4a68" strokeWidth={6} />
      {[-150, -60, 30, 120].map((cx) => <rect key={cx} x={cx} y={-300} width={34} height={260} rx={8} fill="#c3cee6" stroke="#5b6b8e" strokeWidth={3} />)}
      <rect x={-50} y={-130} width={100} height={130} rx={10} fill="#1c2a4c" />
      <rect x={-200} y={-322} width={26} height={310} rx={10} fill="rgba(255,255,255,0.35)" />
      {cerrado > 0 && (
        <g transform={`scale(${cerrado})`}>
          <circle cx={0} cy={-200} r={90} fill="rgba(255,77,77,0.25)" stroke={ROJO} strokeWidth={14} />
          <path d="M -50 -250 L 50 -150 M 50 -250 L -50 -150" stroke={ROJO} strokeWidth={18} strokeLinecap="round" />
        </g>
      )}
      {lupa > 0 && (
        <g transform={`translate(${170 + Math.sin(s * 3) * 20} ${-380 + Math.cos(s * 3) * 10}) scale(${lupa})`}>
          <circle r={70} fill="rgba(180,220,255,0.3)" stroke={ORO} strokeWidth={14} />
          <line x1={50} y1={50} x2={120} y2={120} stroke={ORO} strokeWidth={22} strokeLinecap="round" />
          <ellipse cx={-25} cy={-25} rx={22} ry={12} fill="rgba(255,255,255,0.6)" />
        </g>
      )}
    </g>
  );
};

// Ficha roja con -$40
const Ficha: React.FC<{x: number; y: number; k?: number; rot?: number; ok?: number}> = ({x, y, k = 1, rot = 0, ok = 0}) => (
  <g transform={`translate(${x} ${y}) scale(${k}) rotate(${rot})`}>
    <rect x={-110} y={-62} width={230} height={140} rx={16} fill="rgba(0,0,0,0.3)" />
    <rect x={-120} y={-75} width={240} height={150} rx={16} fill={ok > 0.5 ? '#3fae6a' : 'url(#fichaG)'} stroke={ok > 0.5 ? '#1e6b42' : '#7a1717'} strokeWidth={6} />
    <text x={0} y={22} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={64} fill="#fff">{ok > 0.5 ? '$0' : '-$40'}</text>
    <rect x={-108} y={-66} width={140} height={14} rx={7} fill="rgba(255,255,255,0.45)" />
  </g>
);

// Sitio A: tú te vas con la maleta, pero la ficha te sigue
const Calle: React.FC = () => {
  const {s, spr, lin} = useS();
  const camina = lin(0, T_CUARENTA, 0, 1, Easing.inOut(Easing.sin));
  const yoX = 700 + 120 * camina;
  const cerrado = spr(T_CERRAR, 9, 200);
  const sube = lin(T_REPORTARLA, T_REPORTARLA + 0.5, 0, 1, Easing.in(Easing.cubic));
  const fichaX = interpolate(s, [0, T_CUARENTA], [yoX - 260, 330], clamp);
  const fichaY = 1300 + Math.sin(s * 4) * 18 - sube * 900;
  const kf = 0.8 + 0.4 * spr(T_CUARENTA, 9, 200);
  return (
    <>
      <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{position: 'absolute'}}>
        <Defs />
        <rect x={0} y={1460} width={1080} height={460} fill="rgba(0,0,0,0.35)" />
        <Banco x={330} y={1460} k={1.05} cerrado={cerrado} />
        {/* cuerda de la ficha hasta ti */}
        {s < T_REPORTARLA && <path d={`M ${fichaX + 110} ${fichaY} Q ${(fichaX + yoX) / 2} ${fichaY + 120} ${yoX - 80} 1360`} stroke="rgba(255,120,120,0.8)" strokeWidth={6} fill="none" strokeDasharray="14 10" />}
        <Ficha x={fichaX} y={fichaY} k={kf} rot={Math.sin(s * 2) * 8} />
        {/* tubo hacia arriba */}
        <rect x={290} y={300} width={80} height={900} rx={40} fill="rgba(200,230,255,0.12)" stroke="rgba(200,230,255,0.35)" strokeWidth={5} opacity={lin(T_REPORTARLA - 0.3, T_REPORTARLA, 0, 1)} />
      </svg>
      <Carita x={yoX} y={1330} size={260} color={['#cfe3ff', '#7fb2ff', '#3a6fd8']} saltos={[T_BORRA, T_NEGATIVO, T_SOBRE]} boca={s > T_CERRAR ? 'o' : 'feliz'} />
    </>
  );
};

// Sitio B: archivo de la agencia con cajones; la ficha entra y una lupa la consulta
const Archivo: React.FC = () => {
  const {s, spr, lin} = useS();
  const cae = lin(T_REPORTE - 0.05, T_AGENCIA + 0.3, 0, 1, Easing.out(Easing.bounce));
  const abre = spr(T_HISTORIAL, 10, 160);
  const lupa = spr(T_CONSULTA, 10, 180);
  const ok = lin(T_NEGOCIA, T_ESCRITO, 0, 1);
  const hoja = spr(T_GRATIS, 11, 170);
  return (
    <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{position: 'absolute'}}>
      <Defs />
      <ellipse cx={560} cy={1640} rx={420} ry={40} fill="rgba(0,0,0,0.45)" style={{filter: 'blur(12px)'}} />
      <rect x={180} y={720} width={720} height={920} rx={30} fill="#1f3d31" stroke="#0b1f17" strokeWidth={8} />
      {Array.from({length: 4}).map((_, i) => {
        const dx = i === 1 ? 140 * abre : 0;
        return (
          <g key={i} transform={`translate(${dx} 0)`}>
            <rect x={220} y={760 + i * 215} width={640} height={190} rx={18} fill="url(#cajonG)" stroke="#173a2c" strokeWidth={6} />
            <rect x={470} y={835 + i * 215} width={140} height={34} rx={17} fill={ORO} stroke="#9a6a12" strokeWidth={4} />
            <rect x={232} y={770 + i * 215} width={24} height={170} rx={10} fill="rgba(255,255,255,0.2)" />
          </g>
        );
      })}
      <Ficha x={700 + 140 * abre} y={-300 + cae * 1250} k={0.9} rot={(1 - cae) * 25} ok={ok} />
      {/* consulta del siguiente banco */}
      {lupa > 0 && (
        <g transform={`translate(${880 + Math.sin(s * 3) * 25} ${880 + Math.cos(s * 2.6) * 18}) scale(${lupa})`}>
          <circle r={110} fill="rgba(180,220,255,0.25)" stroke={ORO} strokeWidth={18} />
          <line x1={80} y1={80} x2={170} y2={170} stroke={ORO} strokeWidth={30} strokeLinecap="round" />
          <ellipse cx={-40} cy={-40} rx={34} ry={16} fill="rgba(255,255,255,0.6)" />
        </g>
      )}
      {/* tu reporte gratis */}
      {hoja > 0.001 && (
        <g transform={`translate(330 560) scale(${hoja}) rotate(-6)`}>
          <rect x={-150} y={-200} width={300} height={400} rx={14} fill="#eef2fb" stroke="#8e9bb8" strokeWidth={5} />
          {Array.from({length: 6}).map((_, i) => <rect key={i} x={-110} y={-150 + i * 50} width={i % 2 ? 150 : 220} height={14} rx={7} fill="#b2bdd6" />)}
          {s > T_ERRORES && <circle cx={20} cy={-50} r={50 * spr(T_ERRORES, 8, 220)} fill="none" stroke={ROJO} strokeWidth={10} />}
          <rect x={-140} y={-190} width={26} height={380} rx={12} fill="rgba(255,255,255,0.6)" />
        </g>
      )}
      {/* confirmación por escrito: sello dorado */}
      {s > T_ESCRITO - 0.1 && (
        <g transform={`translate(330 560) scale(${spr(T_ESCRITO, 7, 260)}) rotate(-14)`}>
          <circle r={80} fill="rgba(255,200,61,0.25)" stroke={ORO} strokeWidth={14} />
          <path d="M -35 0 L -8 30 L 42 -30" stroke={ORO} strokeWidth={16} fill="none" strokeLinecap="round" />
        </g>
      )}
    </svg>
  );
};

// Calendario de siete años que pasa hojas
const Calendario: React.FC = () => {
  const {s, spr, lin} = useS();
  const e = spr(T_SIETE - 0.15, 11, 170) * lin(T_GRATIS - 0.3, T_GRATIS, 1, 0);
  if (e <= 0.001) return null;
  const hojas = Math.floor(lin(T_SIETE, T_QUINCENAS + 0.5, 0, 12));
  return (
    <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{position: 'absolute'}}>
      <g transform={`translate(540 1100) scale(${e})`}>
        <rect x={-230} y={-250} width={460} height={500} rx={26} fill="#eef2fb" stroke="#5b6b8e" strokeWidth={8} />
        <rect x={-230} y={-250} width={460} height={110} rx={26} fill={ROJO} />
        {[-130, 130].map((cx) => <rect key={cx} x={cx - 14} y={-290} width={28} height={80} rx={14} fill="#5b6b8e" />)}
        <text x={0} y={90} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={200} fill="#1c2a4c">7</text>
        {Array.from({length: 3}).map((_, i) => {
          const t = (s * 3 + i / 3) % 1;
          return <rect key={i} x={-230} y={-140} width={460} height={60} rx={8} fill="rgba(255,255,255,0.8)" opacity={(1 - t) * (hojas > 0 ? 1 : 0)} transform={`translate(0 ${-t * 220}) rotate(${-t * 30})`} />;
        })}
        <rect x={-220} y={-240} width={30} height={480} rx={14} fill="rgba(255,255,255,0.5)" />
      </g>
    </svg>
  );
};

const Avion: React.FC = () => {
  const {lin} = useS();
  const p = lin(T_ENVIA + 0.1, T_ENVIA + 1.6, 0, 1, Easing.in(Easing.quad));
  if (p <= 0 || p >= 1) return null;
  return (
    <svg width={170} height={170} viewBox="0 0 100 100" style={{position: 'absolute', left: 540 + p * 540, top: 1250 - p * 900 - Math.sin(p * Math.PI) * 150, transform: `rotate(-28deg) scale(${1.1 - p * 0.5})`}}>
      <polygon points="5,50 95,10 60,90 48,58" fill="#ffffff" />
      <polygon points="48,58 95,10 40,70" fill="#b9c8ea" />
    </svg>
  );
};

export const Escena: React.FC = () => {
  const {s, spr, lin} = useS();
  // A: calle (hasta "Ese"), B: archivo (desde "reporte"); siete años en el archivo; cierre en la calle
  const enA = s < T_REPORTE - 0.02 || s >= T_ENVIA - 0.02;
  const sh = sacudida(s, [T_CERRAR, T_AGENCIA + 0.3], 13);
  const deriva = Math.sin(s * 0.5) * 12;
  const paradasA = [
    {t: 0, x: 560, y: 1200, zoom: 1.12},
    {t: T_BORRA, x: 600, y: 1220, zoom: 1.2},
    {t: T_CUARENTA + 0.3, x: 420, y: 1250, zoom: 1.45},
    {t: T_CERRAR + 0.3, x: 380, y: 1150, zoom: 1.15},
    {t: T_REPORTARLA + 0.5, x: 360, y: 800, zoom: 1.0},
  ];
  const paradasB = [
    {t: T_REPORTE, x: 560, y: 900, zoom: 1.3},
    {t: T_AGENCIA + 0.4, x: 600, y: 1100, zoom: 1.05},
    {t: T_HISTORIAL + 0.3, x: 680, y: 1000, zoom: 1.3},
    {t: T_CONSULTA + 0.4, x: 760, y: 950, zoom: 1.4},
    {t: T_SIETE, x: 540, y: 1100, zoom: 1.0},
    {t: T_QUINCENAS + 0.5, x: 540, y: 1080, zoom: 1.15},
    {t: T_GRATIS + 0.3, x: 380, y: 700, zoom: 1.4},
    {t: T_NEGOCIA, x: 560, y: 900, zoom: 1.05},
    {t: T_ESCRITO + 0.4, x: 400, y: 700, zoom: 1.35},
  ];
  const paradasC = [
    {t: T_ENVIA, x: 600, y: 1250, zoom: 1.25},
    {t: T_ENVIA + 2.5, x: 560, y: 1200, zoom: 0.98},
  ];
  return (
    <AbsoluteFill>
      <FondoSitio verde={!enA} />
      <AbsoluteFill style={{transform: `translate(${sh.x + deriva}px, ${sh.y}px)`}}>
        {enA && (
          <Camara paradas={s < T_ENVIA ? paradasA : paradasC} centroY={1080}>
            <Calle />
            <Ondas x={330} y={1260} t0={T_CERRAR} color={ROJO} />
          </Camara>
        )}
        {!enA && (
          <Camara paradas={paradasB} centroY={1080}>
            <Archivo />
            <Ondas x={700} y={950} t0={T_AGENCIA + 0.3} color={ROJO} />
            <Ondas x={330} y={560} t0={T_ESCRITO} color={ORO} />
          </Camara>
        )}
        {!enA && <Calendario />}
        {!enA && s > T_SIGUIENTE - 0.2 && s < T_SIETE && (
          <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{position: 'absolute', opacity: lin(T_SIGUIENTE - 0.2, T_SIGUIENTE + 0.2, 0, 1)}}>
            <Defs />
            <Banco x={880} y={1780} k={0.55 * spr(T_SIGUIENTE, 10, 170)} lupa={spr(T_ABRIRTE, 9, 200)} />
          </svg>
        )}
        <Estela t0={T_REPORTE - 0.05} t1={T_AGENCIA + 0.3} copias={4} render={(t, al) => (
          <div style={{position: 'absolute', left: 620, top: interpolate(t, [T_REPORTE - 0.05, T_AGENCIA + 0.3], [0, 900], clamp), width: 200, height: 120, borderRadius: 16, background: ROJO, opacity: al * 0.6}} />
        )} />
        <Avion />
      </AbsoluteFill>
      {s >= T_CUARENTA && s < T_REPORTE && <Contador desde={0} hasta={40} t0={T_CUARENTA} t1={T_CUARENTA + 0.6} y={430} prefijo="-$" color={ROJO} />}
      {s >= T_SIETE && s < T_GRATIS && <Contador desde={0} hasta={168} t0={T_SIETE} t1={T_QUINCENAS + 0.3} y={430} sufijo=" quincenas" color={ORO} size={70} />}
      {s >= T_GRATIS && s < T_NEGOCIA && <Contador desde={0} hasta={0} t0={T_GRATIS} t1={T_GRATIS + 0.2} y={430} prefijo="$" color={ORO} />}
      <Destello t0={T_CERRAR} fuerza={0.3} />
      <Destello t0={T_ESCRITO} fuerza={0.3} />
      <AbsoluteFill style={{pointerEvents: 'none', background: `radial-gradient(circle at 50% 55%, rgba(255,200,61,${0.07 * lin(T_ESCRITO, T_ESCRITO + 0.5, 0, 1)}), transparent 60%)`}} />
    </AbsoluteFill>
  );
};
